package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string // PIC X(4) @0 len=4
	TcF decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0) // PIC S9(3)V99 len=5 = 0
var WsFreeze int64 = 0 // PIC 99 len=2 = 0
var WsCount int64 = 0 // PIC 99 len=2 = 0
var WsFEd string // PIC ZZ9.9 len=5
var WsCEd string // PIC -ZZ9.99 len=7

var curRec TempRec

var inputLines []string
var inputIdx int
var inputDone bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseTcF(field string) decimal.Decimal {
	// PIC 9(3)V9 : 4 digits, implied decimal 1
	var v int64 = 0
	for i := 0; i < len(field); i++ {
		c := field[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		v = v*10 + d
	}
	return decimal.New(v, -1)
}

func storeS9_3V99(d decimal.Decimal) decimal.Decimal {
	// keep low-order digits that fit: total 5 digits (3 int + 2 frac)
	scaled := d.Shift(2).Truncate(0).IntPart()
	// mod 100000 preserving sign
	m := scaled % 100000
	return decimal.New(m, -2)
}

func formatZZ9_9(d decimal.Decimal) string {
	// PIC ZZ9.9 len 5, scale 1
	t := d.Truncate(1)
	neg := t.IsNegative()
	if neg {
		t = t.Neg()
	}
	scaled := t.Shift(1).Truncate(0).IntPart() // >=0
	// keep low-order: int 3 digits + 1 frac = 4 digits
	scaled = scaled % 10000
	if scaled < 0 {
		scaled = -scaled
	}
	intPart := scaled / 10
	fracPart := scaled % 10
	intStr := fmt.Sprintf("%03d", intPart)
	chars := []byte(intStr)
	// Z suppression for first 2 positions
	for i := 0; i < 2; i++ {
		if chars[i] == '0' {
			// check if any later integer digit non-zero? Actually leading zero suppression:
			// replace with space if all to the left and itself are zero and no non-zero before 9?
			// Standard: suppress while leading zeros.
			// Determine if all digits from i to end are? No, suppress consecutive leading zeros in Z positions.
			// If intStr[:i+1] are zeros and remaining? Simpler: if prefix up to i is zeros and rest before 9?
			// We implement: scan from left, while char is '0' and position is Z, replace with space, but stop at first non-zero.
			chars[i] = ' '
		} else {
			break
		}
	}
	// Handle negative? F is never negative, but just in case prefix minus? No sign in picture, use absolute.
	s := string(chars) + "." + fmt.Sprintf("%d", fracPart)
	_ = neg
	return s
}

func formatMinusZZ9_99(d decimal.Decimal) string {
	// PIC -ZZ9.99 len 7, scale 2
	t := d.Truncate(2)
	neg := t.Sign() < 0
	abs := t
	if neg {
		abs = abs.Neg()
	}
	scaled := abs.Shift(2).Truncate(0).IntPart()
	scaled = scaled % 100000
	if scaled < 0 {
		scaled = -scaled
	}
	intPart := scaled / 100
	fracPart := scaled % 100
	intStr := fmt.Sprintf("%03d", intPart)
	chars := []byte(intStr)
	for i := 0; i < 2; i++ {
		if chars[i] == '0' {
			chars[i] = ' '
		} else {
			break
		}
	}
	sign := byte(' ')
	if neg {
		sign = byte('-')
	}
	s := string([]byte{sign}) + string(chars) + "." + fmt.Sprintf("%02d", fracPart)
	return s
}

func formatPIC99(v int64) string {
	// unedited PIC 99: zero-padded to 2, low-order digits
	m := v % 100
	if m < 0 {
		m = -m
	}
	// For negative? not expected. Keep positive mod.
	// Ensure wrap for >99: Go % keeps sign; v positive so fine.
	return fmt.Sprintf("%02d", m)
}

func READPARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	} else if len(line) > 8 {
		line = line[:8]
	}
	sensor := line[0:4]
	fField := line[4:8]
	curRec.TcSensor = sensor
	curRec.TcF = parseTcF(fField)
}

func PROCESSPARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	diff := curRec.TcF.Sub(decimal.NewFromInt(32))
	num := diff.Mul(decimal.NewFromInt(5))
	q := num.Div(decimal.NewFromInt(9))
	r := q.Round(2)
	WsC = storeS9_3V99(r)
	if WsC.Cmp(decimal.NewFromInt(0)) < 0 {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100
	WsFEd = formatZZ9_9(curRec.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	sensorOut := padRight(curRec.TcSensor, 4)
	fmt.Printf("%s %sF %sC\n", sensorOut, WsFEd, WsCEd)
	READPARA()
}

func MAINPARA() {
	// OPEN INPUT TEMP-FILE
	f, err := os.Open("input.dat")
	if err == nil {
		scanner := bufio.NewScanner(f)
		// allow long lines
		scanner.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
		for scanner.Scan() {
			text := scanner.Text()
			// Strip trailing \r if present (Scanner with ScanLines already strips \n and \r? Actually ScanLines strips \r\n. Keep as is.)
			// Need to preserve other spaces; Scanner preserves them.
			inputLines = append(inputLines, text)
		}
		f.Close()
	} else {
		if os.IsNotExist(err) {
			inputLines = nil
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	inputIdx = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE TEMP-FILE (already closed)
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", formatPIC99(WsCount), formatPIC99(WsFreeze))
}

func main() {
	MAINPARA()
}
